#!/usr/bin/env node
/**
 * Generates src/infrastructure/database/tenant-models.generated.ts from the
 * Prisma schema: every model that has an `organizationId` scalar gets
 * automatic tenant scoping in the Prisma client extension.
 *
 * Runs as part of `npm run prisma:generate`. Commit the generated file.
 */
const fs = require('fs');
const path = require('path');

const schemaPath = path.join(__dirname, '..', 'prisma', 'schema.prisma');
const outPath = path.join(
  __dirname,
  '..',
  'src',
  'infrastructure',
  'database',
  'tenant-models.generated.ts'
);

const src = fs.readFileSync(schemaPath, 'utf8');
const models = [];
const skipped = [];
let current = null;
// Doc comments seen since the last model, so a model can opt out next to its
// own definition rather than in a list that drifts away from the schema.
let docBlock = '';

for (const raw of src.split('\n')) {
  if (/^\s*\/\/\//.test(raw)) {
    docBlock += raw;
    continue;
  }
  const line = raw.replace(/\/\/.*$/, '');
  const open = line.match(/^\s*model\s+(\w+)\s*\{/);
  if (open) {
    // `/// @untenanted` marks a model that carries an organizationId but must
    // NOT be auto-scoped — rows written before a tenant is known, such as an
    // inbound provider webhook. Scoping those would filter on a context that
    // does not exist yet.
    current = { name: open[1], hasOrg: false, optedOut: docBlock.includes('@untenanted') };
    docBlock = '';
    continue;
  }
  docBlock = '';
  if (/^\s*\}/.test(line) && current) {
    if (current.hasOrg && !current.optedOut) models.push(current.name);
    else if (current.hasOrg) skipped.push(current.name);
    current = null;
    continue;
  }
  if (current && /^\s*organizationId\s+String/.test(line)) current.hasOrg = true;
}

const content = `// AUTO-GENERATED by scripts/generate-tenant-models.js — do not edit.
// Regenerate with: npm run prisma:generate
export const TENANT_MODELS: ReadonlySet<string> = new Set([
${models.map((m) => `  '${m}',`).join('\n')}
]);
`;

fs.writeFileSync(outPath, content);
console.log(`✓ tenant-models.generated.ts — ${models.length} tenant-scoped models`);
if (skipped.length) {
  console.log(`  opted out of scoping (@untenanted): ${skipped.join(', ')}`);
}
